class Order {
    OrderId id;
    OrderStatus status;
    Money totalPrice;

    void pay() {
        if (!status.canPay()) {
            throw new IllegalStateException("当前订单不能支付");
        }
        status = OrderStatus.PAID;
    }

    void cancel() {
        if (!status.canCancel()) {
            throw new IllegalStateException("当前订单不能取消");
        }
        status = OrderStatus.CANCELED;
    }
}

enum OrderStatus {
    CREATED,
    PAID,
    CANCELED;

    boolean canPay() {
        return this == CREATED;
    }

    boolean canCancel() {
        return this == CREATED;
    }
}

